import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-FtcyK8lR.js";var l=JSON.parse(`{"path":"/guide/quick-start.html","title":"快速开始","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1772867174000,"contributors":[{"name":"MurphyYi","username":"MurphyYi","email":"zy84338719@hotmail.com","commits":5,"url":"https://github.com/MurphyYi"}],"changelog":[{"hash":"46a94be73dccfa2afd836e97cca5b5781eccb641","time":1772867174000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"fix: 修复文档中所有内部链接使用相对路径"},{"hash":"afed90e9e326cfca3e3e296457c470d99b134c06","time":1772854292000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 为文档添加界面截图"},{"hash":"acf808fd844d46e164aa5b1e98e65abaf9fa76dd","time":1772854092000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 添加完整的 UI配置流程和平台对接文档"},{"hash":"b930b4e44199ef16e3cf03d5fea57d3137d1152c","time":1772853133000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"fix: 修复文档中的死链，移除指向不存在页面的链接"},{"hash":"7bdf9909b19472b012c98787da2927a9e56b5336","time":1772852045000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"feat: 添加文档站点和部署配置更新"}]},"filePathRelative":"guide/quick-start.md"}`),u={name:`quick-start.md`};function d(c,l,u,d,f,p){let m=t(`RouteLink`);return s(),o(`div`,null,[l[7]||=n(`<h1 id="快速开始" tabindex="-1"><a class="header-anchor" href="#快速开始">#</a> 快速开始</h1><p>欢迎使用虹桥计划！本指南将帮助你在 5 分钟内快速体验系统的核心功能。</p><p><img src="/rainbow_bridge/images/home-screenshot-new.png" alt="虹桥计划首页"></p><h2 id="🎯-前置准备" tabindex="-1"><a class="header-anchor" href="#🎯-前置准备">#</a> 🎯 前置准备</h2><p>确保你已经完成了 <a href="./installation">安装部署</a>。如果还没有，请先完成部署。</p><h2 id="🚀-5-分钟快速体验" tabindex="-1"><a class="header-anchor" href="#🚀-5-分钟快速体验">#</a> 🚀 5 分钟快速体验</h2><h3 id="步骤-1-访问管理界面-1-分钟" tabindex="-1"><a class="header-anchor" href="#步骤-1-访问管理界面-1-分钟">#</a> 步骤 1：访问管理界面（1 分钟）</h3><p>打开浏览器访问：http://localhost:8080/rainbow-bridge</p><p>你将看到项目首页，包含：</p><ul><li>项目简介</li><li>核心功能特性</li><li>运行时配置演示</li></ul><h3 id="步骤-2-创建第一个环境-1-分钟" tabindex="-1"><a class="header-anchor" href="#步骤-2-创建第一个环境-1-分钟">#</a> 步骤 2：创建第一个环境（1 分钟）</h3><ol><li>点击左侧导航栏的 <strong>环境管理</strong></li><li>点击 &quot;新建环境&quot; 按钮</li><li>填写环境信息： <ul><li><strong>环境标识</strong>: <code>dev</code></li><li><strong>环境名称</strong>: <code>开发环境</code></li><li><strong>备注</strong>: <code>本地开发测试环境</code></li></ul></li><li>点击 &quot;确定&quot; 保存</li></ol><p>✅ 恭喜！你创建了第一个环境。</p><h3 id="步骤-3-创建第一个渠道-1-分钟" tabindex="-1"><a class="header-anchor" href="#步骤-3-创建第一个渠道-1-分钟">#</a> 步骤 3：创建第一个渠道（1 分钟）</h3><ol><li>在环境列表中找到 <code>开发环境</code></li><li>点击该环境的 &quot;管理渠道&quot; 按钮</li><li>点击 &quot;新建渠道&quot;</li><li>填写渠道信息： <ul><li><strong>渠道标识</strong>: <code>main</code></li><li><strong>渠道名称</strong>: <code>主渠道</code></li><li><strong>备注</strong>: <code>主要开发渠道</code></li></ul></li><li>点击 &quot;确定&quot; 保存</li></ol><p>✅ 现在你有了第一个渠道！</p><h3 id="步骤-4-创建第一个配置-2-分钟" tabindex="-1"><a class="header-anchor" href="#步骤-4-创建第一个配置-2-分钟">#</a> 步骤 4：创建第一个配置（2 分钟）</h3><ol><li>点击左侧导航栏的 <strong>配置管理</strong></li><li>选择环境：<code>开发环境</code>，渠道：<code>主渠道</code></li><li>点击 &quot;新建配置&quot; 按钮</li><li>填写配置信息：</li></ol><p><strong>示例 1：键值对配置</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">配置类型：键值对</span>
<span class="line">名称：max_retry_count</span>
<span class="line">别名：最大重试次数</span>
<span class="line">配置内容：</span>
<span class="line">{</span>
<span class="line">  &quot;max_retry&quot;: 3,</span>
<span class="line">  &quot;timeout&quot;: 5000</span>
<span class="line">}</span>
<span class="line">备注：API 请求重试配置</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>示例 2：纯文本配置</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">配置类型：纯文本</span>
<span class="line">名称：welcome_message</span>
<span class="line">别名：欢迎消息</span>
<span class="line">配置内容：欢迎使用虹桥计划！</span>
<span class="line">备注：首页欢迎文案</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>示例 3：色彩标签配置</strong></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">配置类型：色彩标签</span>
<span class="line">名称：theme_color</span>
<span class="line">别名：主题色</span>
<span class="line">配置内容：#1677FF</span>
<span class="line">备注：应用主题色</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="5"><li>点击 &quot;确定&quot; 保存每个配置</li></ol><p>✅ 你已经掌握了配置管理！</p><h3 id="步骤-5-查看运行时配置-可选" tabindex="-1"><a class="header-anchor" href="#步骤-5-查看运行时配置-可选">#</a> 步骤 5：查看运行时配置（可选）</h3><ol><li>点击 <strong>运行时配置</strong> 页面</li><li>选择环境：<code>开发环境</code>，渠道：<code>主渠道</code></li><li>查看你刚创建的配置</li></ol><p>你也可以通过 API 获取：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> http://localhost:8080/rainbow-bridge/api/v1/runtime/config <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;x-environment: dev&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;x-pipeline: main&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🎉-下一步" tabindex="-1"><a class="header-anchor" href="#🎉-下一步">#</a> 🎉 下一步</h2><p>完成快速体验后，你可以：</p><h3 id="深入学习" tabindex="-1"><a class="header-anchor" href="#深入学习">#</a> 深入学习</h3><ul><li><a href="./installation">安装部署</a> - 详细的安装步骤</li><li><a href="./ui-config/environment">环境管理</a> - 创建和管理环境</li><li><a href="./ui-config/channel">渠道管理</a> - 创建和管理渠道</li><li><a href="./ui-config/config">配置管理</a> - 5 种数据类型的完整说明</li><li><a href="./ui-config/resource">资源管理</a> - 上传和管理静态资源</li></ul><h3 id="平台对接" tabindex="-1"><a class="header-anchor" href="#平台对接">#</a> 平台对接</h3>`,35),i(`ul`,null,[i(`li`,null,[a(m,{to:`/api/`},{default:r(()=>[...l[0]||=[e(`API 文档`,-1)]]),_:1}),l[1]||=e(` - REST API 接口参考`,-1)]),l[2]||=i(`li`,null,[i(`a`,{href:`./integration/frontend`},`平台对接指南`),e(` - 集成到你的项目`)],-1)]),l[8]||=n(`<h3 id="高级功能" tabindex="-1"><a class="header-anchor" href="#高级功能">#</a> 高级功能</h3><ul><li><a href="./ui-config/export">导出配置</a> - 导出为静态包或 ZIP</li><li><a href="./ui-config/migration">配置迁移</a> - 多环境/渠道同步</li></ul><h2 id="💡-最佳实践" tabindex="-1"><a class="header-anchor" href="#💡-最佳实践">#</a> 💡 最佳实践</h2><h3 id="环境命名建议" tabindex="-1"><a class="header-anchor" href="#环境命名建议">#</a> 环境命名建议</h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">dev         - 开发环境</span>
<span class="line">test        - 测试环境</span>
<span class="line">staging     - 预发布环境</span>
<span class="line">prod        - 生产环境</span>
<span class="line">prod-us     - 美国生产环境</span>
<span class="line">prod-eu     - 欧洲生产环境</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="渠道命名建议" tabindex="-1"><a class="header-anchor" href="#渠道命名建议">#</a> 渠道命名建议</h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">main        - 主渠道</span>
<span class="line">hotfix      - 紧急修复渠道</span>
<span class="line">feature-xxx - 特定功能开发渠道</span>
<span class="line">experiment  - 实验性功能渠道</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="配置命名规范" tabindex="-1"><a class="header-anchor" href="#配置命名规范">#</a> 配置命名规范</h3><p>使用有意义的名称，推荐格式：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">模块_功能_属性</span>
<span class="line">api_base_url          # API 基础地址</span>
<span class="line">ui_theme_color        # UI 主题色</span>
<span class="line">feature_new_checkout  # 新功能开关</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="❓-常见问题" tabindex="-1"><a class="header-anchor" href="#❓-常见问题">#</a> ❓ 常见问题</h2><h3 id="q-环境和渠道的区别" tabindex="-1"><a class="header-anchor" href="#q-环境和渠道的区别">#</a> Q: 环境和渠道的区别？</h3><p><strong>A</strong>:</p><ul><li><strong>环境</strong>用于隔离不同的部署场景（如开发、测试、生产）</li><li><strong>渠道</strong>用于在同一环境下管理不同的功能分支或版本线</li></ul><p>例如：</p><ul><li>环境：<code>prod</code>（生产环境）</li><li>渠道：<code>main</code>（正式发布）、<code>hotfix</code>（紧急修复）</li></ul><h3 id="q-配置删除了能恢复吗" tabindex="-1"><a class="header-anchor" href="#q-配置删除了能恢复吗">#</a> Q: 配置删除了能恢复吗？</h3><p><strong>A</strong>: 当前版本不支持回收站功能，删除后无法恢复。建议：</p><ul><li>定期使用导出功能备份配置</li><li>删除前仔细确认</li><li>使用配置迁移功能复制而非修改</li></ul><h3 id="q-如何批量修改配置" tabindex="-1"><a class="header-anchor" href="#q-如何批量修改配置">#</a> Q: 如何批量修改配置？</h3><p><strong>A</strong>:</p><ol><li>使用导出功能导出配置</li><li>本地编辑 JSON 文件</li><li>使用导入功能更新</li></ol><p>或者使用配置迁移功能在不同环境间同步。</p><h2 id="🔗-相关资源" tabindex="-1"><a class="header-anchor" href="#🔗-相关资源">#</a> 🔗 相关资源</h2>`,24),i(`ul`,null,[l[5]||=i(`li`,null,[i(`a`,{href:`./installation`},`完整安装指南`)],-1),i(`li`,null,[a(m,{to:`/api/`},{default:r(()=>[...l[3]||=[e(`API 接口文档`,-1)]]),_:1})]),i(`li`,null,[a(m,{to:`/status/`},{default:r(()=>[...l[4]||=[e(`工程状态`,-1)]]),_:1})]),l[6]||=i(`li`,null,[i(`a`,{href:`https://github.com/yi-nology/rainbow_bridge/issues`,target:`_blank`,rel:`noopener noreferrer`},`GitHub Issues`)],-1)]),l[9]||=i(`p`,null,`祝你使用愉快！🌈`,-1)])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};